"""ufuq -- the target you'll miss is already unavoidable."""

import argparse
import os
import sys
from datetime import date, datetime

from . import agents, report, roster, rules
from .config import Config


def build_parser():
    p = argparse.ArgumentParser(
        prog="ufuq",
        description="Emiratisation runway projection: headcount projections, "
                    "gaps, exposure and the last-safe-requisition date are "
                    "computed, never generated by a model. Compliance is "
                    "decided on accepted offers only -- a plan that works "
                    "when everything lands is not a plan.",
    )
    p.add_argument("roster", help="company snapshot CSV")
    p.add_argument("--pipeline", default=None,
                   help="hires and exits CSV (default: alongside the roster "
                        "file, named pipeline.csv)")
    p.add_argument("-o", "--out", default="projections.csv",
                   help="projection CSV")
    p.add_argument("--config", default=None,
                   help="JSON overriding targets, penalties and time-to-hire")
    p.add_argument("--today", default=None,
                   help="YYYY-MM-DD, for reproducible runs")
    p.add_argument("--company", default=None, help="project one company only")
    p.add_argument("--no-agents", action="store_true",
                   help="computed projection only; no model calls")
    p.add_argument("--fail-on", default="none",
                   choices=("none", "breach", "locked", "held"),
                   help="exit non-zero at this state (for a scheduled run)")
    p.add_argument("--no-colour", action="store_true")
    return p


def build_tasks(portfolio):
    """One task per company with something to advise on.

    A company that is compliant, not applicable, or unprojectable is skipped:
    there is no plan to draft, and asking a model to write about a company
    that needs no action is how filler reassurance gets generated.
    """
    tasks = []
    for p in portfolio.projections:
        if p.state in ("COMPLIANT", "NOT_APPLICABLE", "INSUFFICIENT_DATA"):
            continue
        facts = p.facts()
        tasks.append({
            "company_id": p.company_id,
            "label": f"{p.company_id} {p.company_name} ({p.state})",
            "facts": facts,
            "allowed": agents.expand_evidence(facts),
        })
    return tasks


def main(argv=None):
    args = build_parser().parse_args(argv)

    today = date.today()
    if args.today:
        try:
            today = datetime.strptime(args.today, "%Y-%m-%d").date()
        except ValueError:
            print(f"ufuq: --today must be YYYY-MM-DD, got {args.today}",
                  file=sys.stderr)
            return 2

    try:
        cfg = Config.load(args.config)
    except (OSError, ValueError) as exc:
        print(f"ufuq: config: {exc}", file=sys.stderr)
        return 2

    if not os.path.isfile(args.roster):
        print(f"ufuq: {args.roster} not found", file=sys.stderr)
        return 2

    pipeline_path = args.pipeline or os.path.join(
        os.path.dirname(os.path.abspath(args.roster)), "pipeline.csv")
    if not os.path.isfile(pipeline_path):
        print(f"ufuq: {pipeline_path} not found -- pass --pipeline",
              file=sys.stderr)
        return 2

    try:
        snapshots = roster.load_roster(args.roster)
        events = roster.load_pipeline(pipeline_path)
    except (OSError, ValueError) as exc:
        print(f"ufuq: {exc}", file=sys.stderr)
        return 2

    if args.company:
        snapshots = [s for s in snapshots if s.company_id == args.company]
        if not snapshots:
            print(f"ufuq: company {args.company} not found", file=sys.stderr)
            return 2

    portfolio = rules.assess_all(snapshots, events, cfg, today)

    tasks = build_tasks(portfolio)
    agentic = not args.no_agents and bool(tasks)
    if agentic:
        try:
            tasks = agents.run(tasks)
        except agents.AgentUnavailable as exc:
            print(f"ufuq: {exc}", file=sys.stderr)
            print("ufuq: falling back to the computed projection.",
                  file=sys.stderr)
            agentic = False

    if agentic:
        for t in tasks:
            agents.gate(t, t["allowed"])
        review = tasks
    else:
        review = []

    print(report.terminal(portfolio, cfg, agentic, review,
                          use_colour=not args.no_colour))

    report.write_csv(args.out, portfolio, review)
    print(f"  projections -> {args.out}")
    print("")

    if args.fail_on == "breach" and portfolio.in_breach():
        return 1
    if args.fail_on == "locked" and portfolio.by_state("BREACH_LOCKED"):
        return 1
    if args.fail_on == "held" and any(t.get("status") == "held" for t in review):
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
